"use client";

import * as React from "react";
export interface Plan {
  id: string;
  name: string;
  price: { monthly: number; yearly: number };
  badge?: string;
  limits: { icon: React.ReactNode; label: string; value: string }[];
  sync: string;
  pick: number;
  features: { label: string; included: boolean }[];
  cta?: string;
  onSelect?: (billing: "monthly" | "yearly") => void;
}
interface PricingPlansProps {
  title?: string;
  subtitle?: string;
  plans?: Plan[];
  defaultBilling?: "monthly" | "yearly";
  currency?: string;
  className?: string;
}
function PricingPlans({
  title = `Choose your plan`,
  subtitle = `Find the right plan for your team. Start with a 14-day free trial.`,
  plans = defaultPlans,
  defaultBilling = `yearly`,
  currency = `$`,
  className: className,
}: PricingPlansProps) {
  let [billing, setBilling] = React.useState(defaultBilling),
    [rolling, setRolling] = React.useState(false),
    [detailsOpen, setDetailsOpen] = React.useState(true);
  return (
    <>
      <style href={`ui-pricing-plans`} precedence={`default`}>
        {pricingPlansStyles}
      </style>
      <section className={[`ui-pp`, className].filter(Boolean).join(` `)}>
        <header className={`ui-pp__head`}>
          <h2 className={`ui-pp__title`}>{title}</h2>
          <p className={`ui-pp__subtitle`}>{subtitle}</p>
        </header>
        <div
          className={`ui-pp__switch`}
          role={`radiogroup`}
          aria-label={`Billing period`}
          data-billing={billing}
        >
          <span className={`ui-pp__thumb`} aria-hidden={`true`} />
          {([`monthly`, `yearly`] as const).map((e) => (
            <button
              type={`button`}
              role={`radio`}
              aria-checked={billing === e}
              className={`ui-pp__option`}
              onClick={() => {
                (setBilling(e), setRolling(true));
              }}
              key={e}
            >
              {e === `monthly` ? `Monthly` : `Yearly`}
            </button>
          ))}
        </div>
        <div className={`ui-pp__plans`}>
          {plans.map((e) => (
            <article className={`ui-pp__card`} data-featured={e.badge ? true : void 0} key={e.id}>
              <p className={`ui-pp__name`}>
                {e.name}
                {e.badge && <span className={`ui-pp__badge`}>{e.badge}</span>}
              </p>
              <p className={`ui-pp__price`}>
                <PriceAmount value={e.price[billing]} currency={currency} roll={rolling} />
                <span className={`ui-pp__per`}>{`/per month`}</span>
              </p>
              <hr className={`ui-pp__rule`} />
              <ul className={`ui-pp__limits`}>
                {e.limits.map((e) => (
                  <li key={e.label}>
                    <span className={`ui-pp__limit-label`}>
                      <span className={`ui-pp__icon`}>{e.icon}</span>
                      {e.label}
                    </span>
                    <span className={`ui-pp__limit-value`}>{e.value}</span>
                  </li>
                ))}
              </ul>
              <button
                type={`button`}
                className={`ui-pp__cta`}
