              >
                {e.cta ?? `Start free trial`}
              </button>
              <button
                type={`button`}
                className={`ui-pp__toggle`}
                aria-expanded={detailsOpen}
                onClick={() => setDetailsOpen((e) => !e)}
              >
                {detailsOpen ? `Hide details` : `Show details`}
                <DetailsChevron />
              </button>
              <div
                className={`ui-pp__details`}
                data-open={detailsOpen || void 0}
                inert={!detailsOpen}
              >
