                  <div className={`ui-pp__section-head`}>
                    <span className={`ui-pp__eyebrow`}>{`Integrations`}</span>
                    <span className={`ui-pp__chip`}>{e.sync}</span>
                  </div>
                  <div className={`ui-pp__section-sub`}>
                    <span className={`ui-pp__tag`}>{`Native sync`}</span>
                    <span>
                      {`Choose `}
                      {e.pick}
                      {` of `}
                      {integrationApps.length}
                    </span>
                  </div>
                  <div className={`ui-pp__apps`}>
                    {integrationApps.map((e) => (
                      <span
                        className={`ui-pp__app`}
                        data-filled={e.background ? true : void 0}
                        style={
                          e.background
                            ? {
                                background: e.background,
                              }
                            : void 0
                        }
                        title={e.name}
                        key={e.name}
                      >
                        {e.icon}
                      </span>
                    ))}
                  </div>
                  <ul className={`ui-pp__features`}>
                    {e.features.map((e) => (
                      <li data-included={e.included || void 0} key={e.label}>
                        {e.included ? <IncludedIcon /> : <ExcludedIcon />}
                        <span>{e.label}</span>
                        <span className={`ui-pp__sr`}>
                          {e.included ? `(included)` : `(not included)`}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </article>
          ))}
        </div>
      </section>
    </>
  );
}
function PriceAmount({
  value: value,
  currency: currency,
  roll: rolling,
}: {
  value: number;
  currency: string;
  roll: boolean;
}) {
  let text = `${currency}${value.toLocaleString(`en-US`)}`;
  return rolling ? (
    <span className={`ui-pp__amount`} aria-label={text}>
      {text.split(``).map((e, t) => (
        <span className={`ui-pp__digit`} aria-hidden={`true`} key={`${text.length - t}-${e}`}>
          {e}
        </span>
      ))}
    </span>
  ) : (
    <span className={`ui-pp__amount`}>{text}</span>
  );
}
